// Repli sur '?' plutot qu'une valeur figee : mieux vaut avouer qu'on ne sait pas.
const VERSION     = (typeof GM_info !== 'undefined' && GM_info?.script?.version) || '?';
// ─── [v14.1] REGISTRO DE DIAGNÓSTICO ───────────────────────────────────────────────────────────────────────────────
// Todo lo que hace la extensión queda anotado con hora. Se guarda en el navegador (sobrevive a recargar la página).
const _DG = { lineas: [], max: 6000 };
try { const prev = GM_getValue('cw_diag', []); if (Array.isArray(prev) && prev.length) { _DG.lineas = prev.slice(-800); _DG.lineas.push('------ la página se cargó de nuevo (v' + VERSION + ') ------'); } } catch (e) { /* sin almacenamiento */ }
const _dgHora = () => { const d = new Date(), p = (n, w = 2) => String(n).padStart(w, '0'); return p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds()) + '.' + p(d.getMilliseconds(), 3); };
const _dgTxt = x => { if (x === undefined) return ''; if (typeof x === 'string') return x; try { const t = JSON.stringify(x, (k, v) => (typeof v === 'function' ? '[fn]' : (v instanceof Set ? [...v] : v))); return t && t.length > 2500 ? t.slice(0, 2500) + '…(+' + (t.length - 2500) + ' caracteres)' : t; } catch (e) { return String(x); } };
let _dgTimer = null;
const _dgGuardar = () => { if (_dgTimer) return; _dgTimer = setTimeout(() => { _dgTimer = null; try { GM_setValue('cw_diag', _DG.lineas.slice(-800)); } catch (e) { /* nada */ } }, 4000); };
const _dg = (cat, msg, dato) => {
    try {
        const l = _dgHora() + ' [' + cat + '] ' + msg + (dato !== undefined ? ' ' + _dgTxt(dato) : '');
        _DG.lineas.push(l); if (_DG.lineas.length > _DG.max) _DG.lineas.splice(0, 500);
        _dgGuardar(); console.debug('[CW-DIAG]', l);
    } catch (e) { /* el registro nunca debe romper nada */ }
};
try {
    window.addEventListener('error', e => _dg('ERROR', String(e.message || e) + ' @' + String(e.filename || '').split('/').pop() + ':' + e.lineno));
    window.addEventListener('unhandledrejection', e => _dg('ERROR', 'promesa rechazada: ' + String((e.reason && (e.reason.message || e.reason)) || e.reason)));
} catch (e) { /* nada */ }
