// titre du panneau, en-tete de la fenetre, bouton de carte, @icon). Choix de l'auteur, 01/10/2026.
// ⚠️ Un clipPath par copie : avec un id commun, toutes renverraient a la premiere posee — celle de
// l'onglet, cachee tant qu'il est ferme — et les rayures rouges disparaitraient ailleurs (vu sur WBC).
let wctIcones = 0;
const iconeWct = px => { const id = 'wct-ico-' + (++wctIcones);
    // [Copia personal] icono propio : bloques azul y rojo con « GGB » (misma imagen que @icon).
    return '<svg width="' + px + '" height="' + px + '" viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">' +
        '<rect x="0" y="4" width="23" height="56" fill="#0063AF"/><rect x="23" y="4" width="41" height="56" fill="#E72E39"/>' +
        '<text x="32" y="43" font-family="Arial,Helvetica,sans-serif" font-size="25" font-weight="700" text-anchor="middle" fill="#fff" stroke="#3a0a10" stroke-width="1.8" paint-order="stroke">GGB</text></svg>'; };
// ─── Date helper ───────────────────────────────────────────────────────────
class JDate extends Date {
    clone()       { return new JDate(this); }
    addMinutes(v) { return new JDate(this.getTime() + v * 60000); }
    addDays(v)    { this.setDate(this.getDate() + v); return this; }
}
// ─── Constants & State ─────────────────────────────────────────────────────
const DIR     = { AtoB:1, BtoA:2, TWO:3 };
const NODE_CL = { none:1, inside:2, all:3 };
// Libell\u00E9 de sens affich\u00E9 dans l'UI \u2014 traduit \u00E0 l'appel (t() n'est pas encore d\u00E9fini ici).
// Ne pas remettre de table fig\u00E9e : \u00AB Double sens \u00BB s'affichait en fran\u00E7ais quelle que soit la langue.
const dirStr  = d => d===DIR.TWO ? t('dirBoth') : d===DIR.AtoB ? t('dirAtoB') : t('dirBtoA');
const DIR_CSV = { 1:'A to B', 2:'B to A', 3:'TWO WAY' };

let sdk        = null;
