        const descripcion = String((e.config && e.config.reason) || '').trim().slice(0, 1000);
        if (!evento && !descripcion) { logApply(_cwT('sinEvento'), 'info'); return; }
        const ventanas = ventanasCl.map(cl => ({ ini: _cwFH(cl.start), fin: _cwFH(cl.end) }));
        if (!ventanas.length) return;
        const carga = { evento, descripcion, ventanas, version: VERSION, usuario: await _cwUsuario(), eventoId: mteId ? String(mteId) : '' };   // v2.2: quién cargó · v16.6: identificador del evento de Waze en que se cargó
