        if (okW) { try { GM_setValue('cw_senal_web', { ts: Date.now(), exp: okW.datos.expediente || '' }); } catch (e) { /* sin almacenamiento */ } }
        if (p.ok && p.datos && p.datos.resultado === 'parcial' && carga.plan) logApply(_cwT('parcial', carga.plan.cargadas.length, carga.plan.total), 'info');   // [v17.2]
