const _CW_ENLP_K = 'cw_enlaces_pend', _CW_ENLP_VIDA = 48 * 3600 * 1000;
const _cwEnlPLeer = () => { try { const v = GM_getValue(_CW_ENLP_K, []); return (Array.isArray(v) ? v : []).filter(p => p && p.cuerpo && p.cuerpo.cierre && p.cuerpo.eventoId && Date.now() - (p.ts || 0) < _CW_ENLP_VIDA); } catch (e) { return []; } };
const _cwEnlPGuardar = l => { try { GM_setValue(_CW_ENLP_K, l.slice(-30)); } catch (e) { /* sin almacenamiento */ } };
const _cwEnlPAgregar = cuerpo => { const l = _cwEnlPLeer().filter(p => !(p.cuerpo.cierre === cuerpo.cierre && p.cuerpo.eventoId === cuerpo.eventoId)); l.push({ cuerpo, ts: Date.now(), n: 0 }); _cwEnlPGuardar(l); _cwReg('el aviso de «evento guardado» no llegó a la web: queda pendiente y se reintenta'); };
