    const b = r.bbox, lon = (b[0] + b[2]) / 2, lat = (b[1] + b[3]) / 2, ids = r.ids;
    const fu = _planEscaneo && _planEscaneo.fuente;
    const hayLocal = fu ? ids.some(id => { const sg = fu.segs.get(Number(id)); return !sg || !_planPrincipal(sg.roadType); }) : true;
    const zMin = hayLocal ? 16 : 14;
