            { const vs = (g.vistas && g.vistas.length) ? g.vistas : (g.vista ? [g.vista] : []); if (vs.length && g.ids.some(id => !getSegById(id))) await _planAcumular(g.ids, vs); }   // [v17.5] vuelve a cargar el tramo repitiendo sus vistas (la selección acumulada mantiene cargado lo ya visto)
            vivos = g.ids.filter(id => getSegById(id));
