        if (b.dataset.planIgnorar) { const tid = Number(b.dataset.planIgnorar); if (_plan) { if (!_plan.ignora) _plan.ignora = {}; _plan.ignora[tid] = true; if (_plan.cubre) delete _plan.cubre[tid]; if (_planEdTid === tid) _planEdTid = null; _planPlayFallos = _planPlayFallos.filter(f => f.tid !== tid); _planWarn = null; _planActivoId = null; _planScroll = true; _planGuardar(); _planRedibujar(true); const tt = _plan.p.tramos.find(x => x.id === tid); showToast('🚫 Tramo ' + (tt ? _planNum(tt) : '') + ' ignorado: no se cargará. Puedes reponerlo con «↩ Reponer».', 4500, '#546e7a'); } return; }   // [v17.5]
